import warnings
from typing import Any

from pydantic import field_validator

from llmcompressor.core import Event, EventType, ModelParameterizedLayer, State
from llmcompressor.modifiers import Modifier
from llmcompressor.modifiers.pruning.helpers import (
    PruningCreateSettings,
    PruningSchedulerFactory,
    SchedulerCalculationType,
)
from llmcompressor.modifiers.pruning.utils.pytorch import (
    LayerParamMasking,
    MaskCreatorType,
    PruningMaskCreatorArgs,
    PruningMaskFactory,
)
from llmcompressor.utils.pytorch.module import build_parameterized_layers

__all__ = ["MagnitudePruningModifier"]


class MagnitudePruningModifier(Modifier, LayerParamMasking):
    targets: str | list[str]
    init_sparsity: float
    final_sparsity: float
    update_scheduler: str = "cubic"
    scheduler_args: dict[str, Any] = {}
    mask_structure: str = "unstructured"
    leave_enabled: bool = False
    apply_globally: bool = False

    parameterized_layers_: dict[str, ModelParameterizedLayer] = None
    _save_masks: bool = False
    _use_hooks: bool = False
    scheduler_function_: SchedulerCalculationType = None
    mask_creator_function_: MaskCreatorType = None
    current_sparsity_: float = None

    @field_validator("leave_enabled")
    def validate_leave_enabled(value: bool) -> bool:
        if value:
            warnings.warn(
                "MagnitudePruningModifier.leave_enabled has been deprecated "
                "and will be set to False.",
                DeprecationWarning,
            )
        return False

    def on_initialize(self, state: State, **kwargs) -> bool:
        if self.apply_globally:
            raise NotImplementedError("global pruning not implemented yet for PyTorch")

        if "save_masks" in kwargs:
            self._save_masks = kwargs["save_masks"]
        if "use_hooks" in kwargs:
            self._use_hooks = kwargs["use_hooks"]

        if not state.model:
            return False

        self.scheduler_function_ = PruningSchedulerFactory.create_scheduler(
            self.update_scheduler,
            PruningCreateSettings(
                self.start,
                self.end,
                self.update,
                self.init_sparsity,
                self.final_sparsity,
                self.scheduler_args,
            ),
        )
        self.mask_creator_function_ = PruningMaskFactory.create_mask_creator(
            self.mask_structure
        )

        self.parameterized_layers_ = build_parameterized_layers(
            state.model, self.targets
        )

        for layer_param_name, parameterized_layer in self.parameterized_layers_.items():
            self.add_mask(
                layer_param_name,
                parameterized_layer,
                persistent=self._save_masks,
                add_hooks=self._use_hooks,
            )

        return True

    def on_finalize(self, state: State, **kwargs) -> bool:
        for layer_param_name, _ in self.parameterized_layers_.items():
            self.remove_mask(layer_param_name)

        return True

    def on_start(self, state: State, event: Event, **kwargs):
        sparsity = self.scheduler_function_(event, state)
        self.current_sparsity_ = sparsity

        for layer_param_name, parameterized_layer in self.parameterized_layers_.items():
            mask = self.mask_creator_function_(
                PruningMaskCreatorArgs(
                    parameter=parameterized_layer.param,
                    sparsity=sparsity,
                    scores=parameterized_layer.param.data.abs(),
                )
            )
            self.update_mask(layer_param_name, mask)

        self.enable_masks()

    def on_update(self, state: State, event: Event, **kwargs):
        if event.type_ == EventType.BATCH_START:
            sparsity = self.scheduler_function_(event, state)
            if sparsity != self.current_sparsity_:
                self.current_sparsity_ = sparsity

                for (
                    layer_param_name,
                    parameterized_layer,
                ) in self.parameterized_layers_.items():
                    mask = self.mask_creator_function_(
                        PruningMaskCreatorArgs(
                            parameter=parameterized_layer.param,
                            sparsity=sparsity,
                            scores=parameterized_layer.param.data.abs(),
                        )
                    )
                    self.update_mask(layer_param_name, mask)
        else:
            self._update_masks(event)

    def on_end(self, state: State, event: Event, **kwargs):
        self.disable_masks()

    def _update_masks(self, event: Event):
        if event.type_ == EventType.OPTIM_PRE_STEP and not self._use_hooks:
            for layer_param_name, _ in self.parameterized_layers_.items():
                self.apply_mask_gradient(layer_param_name)
        elif event.type_ == EventType.OPTIM_POST_STEP and not self._use_hooks:
            for layer_param_name, _ in self.parameterized_layers_.items():
                self.apply_mask_weight(layer_param_name)

"""
Helper functions and utilities for pruning modifiers.

Provides scheduling functions, factory classes, and configuration
utilities for pruning operations. Includes linear and cubic schedulers,
custom scheduler creation, and settings management for structured and
"""

import math
import re
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

from llmcompressor.core import Event, State

__all__ = [
    "PruningCreateSettings",
    "SchedulerCalculationType",
    "CreateSchedulerType",
    "PruningSchedulerFactory",
    "create_custom_scheduler",
    "linear_scheduler",
    "cubic_scheduler",
    "polynomial_decay_scheduler",
    "polynomial_scheduler",
    "multi_step_scheduler",
]


@dataclass
class PruningCreateSettings:
    start: float
    end: float
    update: float
    init_sparsity: float
    final_sparsity: float
    args: dict[str, Any]


SchedulerCalculationType = Callable[[Event, State], float]
CreateSchedulerType = Callable[[PruningCreateSettings], SchedulerCalculationType]


class PruningSchedulerFactory:
    registry: dict[str, CreateSchedulerType] = {}

    @staticmethod
    def register(name: str, func: CreateSchedulerType):
        PruningSchedulerFactory.registry[name] = func

    @staticmethod
    def register_decorator(name: str):
        def inner(func: CreateSchedulerType):
            PruningSchedulerFactory.registry[name] = func
            return func

        return inner

    @staticmethod
    def create_scheduler(
        scheduler_type: str, settings: PruningCreateSettings
    ) -> SchedulerCalculationType:
        if scheduler_type in PruningSchedulerFactory.registry:
            return PruningSchedulerFactory.registry[scheduler_type](settings)
        elif scheduler_type.startswith("calc(") and scheduler_type.endswith(")"):
            return create_custom_scheduler(scheduler_type, settings)
        else:
            raise ValueError(f"Unknown scheduler type: {scheduler_type}")


def create_custom_scheduler(
    scheduler_type: str, settings: PruningCreateSettings
) -> SchedulerCalculationType:
    pattern = re.compile(r"calc\(([^()]*)\)")
    match = pattern.search(scheduler_type)

    if not match:
        raise ValueError(f"invalid calc string {scheduler_type}")

    inner_expr = match.group(1)

    def _schedule(event: Event, state: State):
        return eval(
            inner_expr,
            {"math": math},
            {
                "start": settings.start,
                "end": settings.end,
                "update": settings.update,
                "init_sparsity": settings.init_sparsity,
                "final_sparsity": settings.final_sparsity,
                **(settings.args if settings.args else {}),
                "index": event.current_index,
            },
        )

    return _schedule


@PruningSchedulerFactory.register_decorator("linear")
def linear_scheduler(settings: PruningCreateSettings) -> SchedulerCalculationType:
    def _schedule(event: Event, state: State) -> float:
        per_complete = (event.current_index - settings.start) / (
            settings.end - settings.start
        )

        return (
            settings.init_sparsity
            + (settings.final_sparsity - settings.init_sparsity) * per_complete
        )

    return _schedule


@PruningSchedulerFactory.register_decorator("cubic")
def cubic_scheduler(settings: PruningCreateSettings) -> SchedulerCalculationType:
    settings.args = {"exponent": 3}

    return polynomial_decay_scheduler(settings)


@PruningSchedulerFactory.register_decorator("polynomial_decay")
def polynomial_decay_scheduler(
    settings: PruningCreateSettings,
) -> SchedulerCalculationType:
    args = settings.args if settings.args else {}
    exponent = args.get("exponent", 2)

    def _schedule(event: Event, state: State) -> float:
        per_complete = (event.current_index - settings.start) / (
            settings.end - settings.start
        )

        scaled_complete = pow(per_complete - 1, exponent) + 1

        return (
            settings.init_sparsity
            + (settings.final_sparsity - settings.init_sparsity) * scaled_complete
        )

    return _schedule


@PruningSchedulerFactory.register_decorator("polynomial")
def polynomial_scheduler(settings: PruningCreateSettings) -> SchedulerCalculationType:
    args = settings.args if settings.args else {}
    exponent = args.get("exponent", 2)

    def _schedule(event: Event, state: State) -> float:
        per_complete = (event.current_index - settings.start) / (
            settings.end - settings.start
        )
        scaled_complete = per_complete**exponent

        return (
            settings.init_sparsity
            + (settings.final_sparsity - settings.init_sparsity) * scaled_complete
        )

    return _schedule


@PruningSchedulerFactory.register_decorator("multi_step")
def multi_step_scheduler(settings: PruningCreateSettings) -> SchedulerCalculationType:
    args = settings.args if settings.args else {}
    steps = args.get("steps", [])
    steps = sorted(steps, key=lambda x: x[0])

    def _schedule(event: Event, state: State) -> float:
        current_sparsity = settings.init_sparsity

        for index, sparsity in steps:
            if event.current_index >= index:
                current_sparsity = sparsity

        return current_sparsity

    return _schedule
